        "max_chars": {
            "statement": 100,
            "highlight": 32,
            "bgColor": 32,
            "textColor": 32,
        },
    },
}


def _json_object(raw: str, source: str) -> dict[str, Any]:
    value = json.loads(raw)
    if not isinstance(value, dict):
        raise ValueError(f"expected a JSON object in {source}")
    return cast(dict[str, Any], value)


def _json_array(raw: str, source: str) -> list[dict[str, Any]]:
    value = json.loads(raw)
    if not isinstance(value, list) or not all(isinstance(item, dict) for item in value):
        raise ValueError(f"expected a JSON object array in {source}")
    return cast(list[dict[str, Any]], value)


def _safe_relative(path: str) -> str:
    normalized = PurePosixPath(path.replace("\\", "/"))
    if normalized.is_absolute() or ".." in normalized.parts:
        raise ValueError(f"unsafe template path: {path}")
    return normalized.as_posix()


@dataclass(frozen=True)
class PackReader:
    source: Path
    kind: str
    sha256: str
    prefix: str = ""

    @classmethod
    def open(cls, source: Path) -> PackReader:
        source = source.resolve()
        if source.is_file() and zipfile.is_zipfile(source):
            digest = hashlib.sha256(source.read_bytes()).hexdigest()
            with zipfile.ZipFile(source) as archive:
                names = [name for name in archive.namelist() if not name.endswith("/")]
            candidates = sorted(
                name[: -len("index.json")]
                for name in names
                if name == "index.json" or name.endswith("/index.json")
            )
            if len(candidates) != 1:
                raise ValueError("template ZIP must contain exactly one index.json")
            return cls(source=source, kind="zip", sha256=digest, prefix=candidates[0])
        if source.is_dir():
            root = _find_directory_root(source)
            digest = _directory_hash(root)
            return cls(source=root, kind="directory", sha256=digest)
        raise ValueError(f"motion pack is neither a ZIP nor a directory: {source}")

    def read_bytes(self, relative: str) -> bytes:
        relative = _safe_relative(relative)
        if self.kind == "zip":
            with zipfile.ZipFile(self.source) as archive:
                try:
                    return archive.read(f"{self.prefix}{relative}")
                except KeyError as error:
                    raise FileNotFoundError(relative) from error
        path = (self.source / Path(relative)).resolve()
        if not path.is_relative_to(self.source):
            raise ValueError(f"template path escapes pack root: {relative}")
        return path.read_bytes()

    def read_text(self, relative: str) -> str:
        return self.read_bytes(relative).decode("utf-8")

    def copy(self, relative: str, destination: Path) -> None:
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(self.read_bytes(relative))


def _find_directory_root(source: Path) -> Path:
    direct = source / "index.json"
    if direct.is_file():
        return source.resolve()
    candidates = sorted(path.parent for path in source.rglob("index.json"))
    if len(candidates) != 1:
        raise ValueError("template directory must contain exactly one index.json")
    return candidates[0].resolve()


def _directory_files(root: Path) -> Iterator[Path]:
    yield from sorted(
        (path for path in root.rglob("*") if path.is_file()), key=lambda p: p.as_posix()
    )


def _directory_hash(root: Path) -> str:
    digest = hashlib.sha256()
    for path in _directory_files(root):
        relative = path.relative_to(root).as_posix().encode("utf-8")
        data = path.read_bytes()
        digest.update(len(relative).to_bytes(8, "big"))
        digest.update(relative)
        digest.update(len(data).to_bytes(8, "big"))
        digest.update(data)
    return digest.hexdigest()


def _static_parse(source: str, expected_component: str) -> dict[str, Any]:
    incomplete = re.search(r"\{\s*[A-Za-z_$][\w.$]*\s*&&\s*\}", source)
    if incomplete:
        return {
            "status": "broken",
            "parser": "palantum-static-v1",
            "confidence": 1.0,
            "reason": "incomplete JSX conditional expression",
        }
    export = re.search(r"export\s+const\s+([A-Za-z_$][\w$]*)", source)
    if not export:
        return {
            "status": "broken",
            "parser": "palantum-static-v1",
            "confidence": 0.95,
            "reason": "no exported component declaration found",
        }
    if export.group(1) != expected_component:
        return {
            "status": "broken",
            "parser": "palantum-static-v1",
            "confidence": 0.95,
            "reason": (
                f"exported component {export.group(1)!r} does not match "
                f"metadata componentName {expected_component!r}"
            ),
        }
    if not re.search(r"from\s+['\"]remotion['\"]", source):
        return {
            "status": "broken",
            "parser": "palantum-static-v1",
            "confidence": 0.9,
            "reason": "component does not import Remotion",
        }
    return {
        "status": "ok",
        "parser": "palantum-static-v1",
        "confidence": 0.8,
        "reason": None,
    }


def _slots(metadata: dict[str, Any], limits: dict[str, int]) -> list[dict[str, Any]]:
    raw_slots = metadata.get("editableProps", [])
    if not isinstance(raw_slots, list):
        raise ValueError(f"editableProps must be an array for {metadata.get('id')}")
    result: list[dict[str, Any]] = []
    for raw in raw_slots:
        if not isinstance(raw, dict) or not isinstance(raw.get("key"), str):
            raise ValueError(f"invalid editable prop for {metadata.get('id')}")
        key = str(raw["key"])
        default = raw.get("defaultValue", "")
        result.append(
            {
                "key": key,
                "type": str(raw.get("type", "string")),
                "label": str(raw.get("label", key)),
                "default": default,
                "max_chars": int(limits.get(key, max(32, min(240, len(str(default)) * 2)))),
            }
        )
    return result


def _scene(reader: PackReader, entry: dict[str, Any], curated: dict[str, Any]) -> dict[str, Any]:
    scene_id = str(entry.get("id", ""))
    component_path = _safe_relative(str(entry.get("file", f"{scene_id}/Composition.tsx")))
    metadata_path = f"{PurePosixPath(component_path).parent.as_posix()}/metadata.json"
    metadata = _json_object(reader.read_text(metadata_path), metadata_path)
    component_name = str(metadata.get("componentName", entry.get("componentName", "")))
    source = reader.read_text(component_path)
    static_parse = _static_parse(source, component_name)
    return {
        "id": scene_id,
        "name": str(metadata.get("name", scene_id)),
        "beat_type": str(curated["beat_type"]),
        "confidence": float(curated["confidence"]),
        "engine": "remotion",
        "component_name": component_name,
        "component_path": component_path,
        "metadata_path": metadata_path,
        "duration_s": float(metadata["duration"]),
        "duration_in_frames": int(metadata["durationInFrames"]),
        "fps": int(metadata["fps"]),
        "width": int(metadata["width"]),
        "height": int(metadata["height"]),
        "slots": _slots(metadata, cast(dict[str, int], curated["max_chars"])),
        "status": static_parse["status"],
        "broken_reason": static_parse["reason"],
        "static_parse": static_parse,
    }


def build_scene_catalog(source: Path, output: Path) -> dict[str, Any]:
    """Scan the curated subset of an external pack and cache its catalog by source hash."""
    reader = PackReader.open(source)
    if output.exists():
        try:
            cached = _json_object(output.read_text(), str(output))
            cached_source = cached.get("source")
            if (
                cached.get("schema_version") == CATALOG_SCHEMA_VERSION
                and cached.get("curation_version") == CURATION_VERSION
                and isinstance(cached_source, dict)
                and cached_source.get("sha256") == reader.sha256
                and cached.get("source_sha256") == reader.sha256
            ):
                return cached
        except (OSError, TypeError, ValueError, json.JSONDecodeError):
            pass

    index = _json_array(reader.read_text("index.json"), "index.json")
    by_id = {str(item.get("id", "")): item for item in index}
    scenes: list[dict[str, Any]] = []
    for scene_id, curated in CURATED_SCENES.items():
        entry = by_id.get(scene_id)
        if entry is None:
            scenes.append(
                {
                    "id": scene_id,
                    "beat_type": curated["beat_type"],
                    "confidence": curated["confidence"],
                    "engine": "remotion",
                    "status": "broken",
                    "broken_reason": "curated scene is missing from index.json",
                    "static_parse": {
                        "status": "broken",
                        "parser": "palantum-static-v1",
                        "confidence": 1.0,
                        "reason": "curated scene is missing from index.json",
                    },
                }
            )
            continue
        try:
            scenes.append(_scene(reader, entry, curated))
        except (FileNotFoundError, KeyError, TypeError, ValueError, UnicodeDecodeError) as error:
            scenes.append(
                {
                    "id": scene_id,
                    "beat_type": curated["beat_type"],
                    "confidence": curated["confidence"],
                    "engine": "remotion",
                    "status": "broken",
                    "broken_reason": f"{type(error).__name__}: {error}",
                    "static_parse": {
                        "status": "broken",
                        "parser": "palantum-static-v1",
                        "confidence": 1.0,
                        "reason": f"{type(error).__name__}: {error}",
                    },
                }
            )
    catalog: dict[str, Any] = {
        "schema_version": CATALOG_SCHEMA_VERSION,
        "curation_version": CURATION_VERSION,
        "source_sha256": reader.sha256,
        "source": {
            "kind": reader.kind,
            "name": reader.source.name,
            "sha256": reader.sha256,
        },
        "scenes": scenes,
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(catalog, indent=2, ensure_ascii=False) + "\n")
    return catalog

from __future__ import annotations

import json
import os
import re
from pathlib import Path
from typing import Any

from palantum.motion.catalog import PackReader, build_scene_catalog

REMOTION_VERSION = "4.0.0"


def _scene(catalog: dict[str, Any], scene_id: str) -> dict[str, Any]:
    scenes = catalog.get("scenes", [])
    if not isinstance(scenes, list):
        raise ValueError("scene catalog has no scenes array")
    for value in scenes:
        if isinstance(value, dict) and value.get("id") == scene_id:
            return value
    raise KeyError(f"scene is not curated: {scene_id}")


def _props(scene: dict[str, Any], supplied: dict[str, Any] | None) -> dict[str, Any]:
    slots = scene.get("slots", [])
    if not isinstance(slots, list):
        raise ValueError("scene has no valid slots")
    defaults = {
        str(slot["key"]): slot.get("default", "")
        for slot in slots
        if isinstance(slot, dict) and isinstance(slot.get("key"), str)
    }
    limits = {
        str(slot["key"]): int(slot["max_chars"])
        for slot in slots
        if isinstance(slot, dict)
        and isinstance(slot.get("key"), str)
        and isinstance(slot.get("max_chars"), int)
    }
    supplied = supplied or {}
    unknown = sorted(set(supplied) - set(defaults))
    if unknown:
        raise ValueError(f"undeclared scene props: {', '.join(unknown)}")
    merged = defaults | supplied
    for key, value in merged.items():
        if not isinstance(value, str):
            raise ValueError(f"scene prop {key} must be a string")
        if len(value) > limits[key]:
            raise ValueError(f"scene prop {key} exceeds max_chars={limits[key]}")
    return merged


def _package_json(needs_lucide: bool) -> dict[str, Any]:
    dependencies = {
        "@remotion/cli": REMOTION_VERSION,
        "remotion": REMOTION_VERSION,
        "react": "18.2.0",
        "react-dom": "18.2.0",
    }
    if needs_lucide:
        dependencies["lucide-react"] = "0.468.0"
    return {
        "name": "palantum-motion-slot",
        "version": "0.0.0",
        "private": True,
        "scripts": {"render": "remotion render src/index.ts Scene output.mov"},
        "dependencies": dependencies,
        "devDependencies": {
            "@types/react": "18.2.79",
            "@types/react-dom": "18.2.25",
            "typescript": "5.5.4",
        },
    }


def materialize_scene(
    source: Path,
    scene_id: str,
    edit_dir: Path,
    props: dict[str, Any] | None = None,
    slot_id: str | None = None,
    target_width: int | None = None,
    target_height: int | None = None,
) -> Path:
    """Copy one curated scene into an isolated, renderable edit/animations slot."""
    if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", scene_id):
        raise ValueError(f"unsafe scene id: {scene_id}")
    slot_id = slot_id or scene_id
    if not re.fullmatch(r"[a-z0-9]+(?:[-_][a-z0-9]+)*", slot_id):
        raise ValueError(f"unsafe slot id: {slot_id}")
    catalog_path = edit_dir / "scene-catalog.json"
    catalog = build_scene_catalog(source, catalog_path)
    scene = _scene(catalog, scene_id)
    parse = scene.get("static_parse")
    if not isinstance(parse, dict) or parse.get("status") != "ok":
        reason = parse.get("reason") if isinstance(parse, dict) else "unknown parse failure"
        raise ValueError(f"scene {scene_id} is broken: {reason}")
    slot = edit_dir / "animations" / f"slot_{slot_id}"
    src = slot / "src"
    src.mkdir(parents=True, exist_ok=True)
    reader = PackReader.open(source)
    reader.copy(str(scene["component_path"]), src / "Composition.tsx")
    reader.copy(str(scene["metadata_path"]), slot / "metadata.json")
    resolved_props = _props(scene, props)
    (slot / "props.json").write_text(
        json.dumps(resolved_props, indent=2, ensure_ascii=False) + "\n"
    )
    component_name = str(scene["component_name"])
    scene_width = int(scene["width"])
    scene_height = int(scene["height"])
    target_width = target_width or scene_width
    target_height = target_height or scene_height
    if target_width <= 0 or target_height <= 0:
        raise ValueError("target dimensions must be positive")
    scale = min(target_width / scene_width, target_height / scene_height)
    root = f"""import React from 'react';
import {{AbsoluteFill, Composition}} from 'remotion';
import props from '../props.json';
import {{{component_name}}} from './Composition';

const SceneCanvas: React.FC = () => (
  <AbsoluteFill style={{{{
    backgroundColor: 'transparent',
    alignItems: 'center',
    justifyContent: 'center',
  }}}}>
    <div style={{{{
      width: {scene_width},
      height: {scene_height},
      position: 'relative',
      flex: '0 0 auto',
      overflow: 'hidden',
      transform: 'scale({scale:.8f})',
      transformOrigin: 'center center',
    }}}}>
      <{component_name} {{...props}} />
    </div>
  </AbsoluteFill>
);

export const RemotionRoot: React.FC = () => (
  <Composition
    id="Scene"
    component={{SceneCanvas}}
    durationInFrames={{{int(scene["duration_in_frames"])}}}
    fps={{{int(scene["fps"])}}}
    width={{{target_width}}}
    height={{{target_height}}}
  />
);
"""
    (src / "Root.tsx").write_text(root)
    (src / "index.ts").write_text(
        "import {registerRoot} from 'remotion';\n"
        "import {RemotionRoot} from './Root';\n\n"
        "registerRoot(RemotionRoot);\n"
    )
    package = _package_json("lucide-react" in (src / "Composition.tsx").read_text())
    (slot / "package.json").write_text(json.dumps(package, indent=2) + "\n")
    tsconfig = {
        "compilerOptions": {
            "target": "ES2020",
            "module": "ESNext",
            "moduleResolution": "Bundler",
            "jsx": "react-jsx",
            "strict": True,
            "esModuleInterop": True,
            "resolveJsonModule": True,
            "skipLibCheck": True,
        },
        "include": ["src", "props.json"],
    }
    (slot / "tsconfig.json").write_text(json.dumps(tsconfig, indent=2) + "\n")
    manifest = {
        "scene_id": scene_id,
        "source_sha256": catalog["source"]["sha256"],
        "catalog": str(catalog_path),
        "output": "render.mov",
        "target_width": target_width,
        "target_height": target_height,
    }
    (slot / "palantum-slot.json").write_text(json.dumps(manifest, indent=2) + "\n")
    return slot


def build_render_command(slot: Path, output: Path | None = None) -> list[str]:
    """Return the deterministic Remotion CLI invocation for a ProRes 4444 alpha MOV."""
    output = output or slot / "render.mov"
    launcher = (
        [os.environ.get("COMSPEC", "cmd.exe"), "/d", "/s", "/c", "npx"]
        if os.name == "nt"
        else ["npx"]
    )
    return [
        *launcher,
        "--no-install",
        "remotion",
        "render",
        str(slot / "src" / "index.ts"),
        "Scene",
        str(output),
        "--codec=prores",
        "--prores-profile=4444",
        "--pixel-format=yuva444p10le",
        "--image-format=png",
        f"--props={slot / 'props.json'}",
    ]

