+async function pollJobActivity() {
+  if (MOCK) return;
+  state.jobActivityPolling = true;
+  try {
+    const response = await fetch('/api/activity');
+    if (response.ok) {
+      const data = await response.json();
+      renderAgentActivity(data.sessions || []);
+    }
+  } catch (_) {}
+  const keepPolling = state.uploading || state.pollingRecommendations || state.finalizing;
+  if (keepPolling) {
+    state.jobActivityPollTimer = setTimeout(pollJobActivity, 1200);
+  } else {
+    state.jobActivityPollTimer = null;
+    state.jobActivityPolling = false;
+  }
+}
+
+function startJobActivityPolling() {
+  if (MOCK || state.jobActivityPolling || state.jobActivityPollTimer) return;
+  pollJobActivity();
+}
+
+function stopJobActivityPolling() {
+  clearTimeout(state.jobActivityPollTimer);
+  state.jobActivityPollTimer = null;
+  state.jobActivityPolling = false;
+  renderAgentActivity();
+}
