+    } else {
+      showJobStatus({
+        tone: 'success',
+        title: 'Varianten sind bereit',
+        detail: 'Du kannst jetzt die Schnittvarianten vergleichen und auswählen.',
+        eta: 'Abgeschlossen',
+        progress: 100,
+        autoHide: 7000,
+      });
+    }
+    return;
+  }
+
+  if (phase === 'done' && data.video_url) {
+    showJobStatus({
+      tone: 'success',
+      title: 'Video ist fertig',
+      detail: 'Das finale Video kann jetzt angesehen oder exportiert werden.',
+      eta: 'Abgeschlossen',
+      progress: 100,
+      autoHide: 10000,
+    });
+    return;
+  }
+
+  hideJobStatus();
+  setProgressValue(0);
+}
