import { AbsoluteFill, useCurrentFrame, spring, interpolate, useVideoConfig } from 'remotion'
export const HeroStatCallout: React.FC<{
  variant?: string
  heroValue?: string
  heroLabel?: string
  stats?: string
  bgColor?: string
}> = ({
  variant = 'default',
  heroValue = '17%',
  heroLabel = 'Year over Year Growth',
  stats = 'Revenue $4.2M,Users 28K,NPS 72',
  bgColor = '#f5f5f5',
}) => {
  const frame = useCurrentFrame()
  const { fps } = useVideoConfig()
  const s = {
    fontFamily: 'system-ui, sans-serif',
    fontWeight: 600,
    letterSpacing: '-0.02em',
    borderRadius: 12,
    shadow: undefined,
    borderWidth: 1,
    borderColor: '#e5e5e5',
    card: { borderRadius: 12, border: '1px solid #e5e5e5', boxShadow: undefined, background: undefined },
    text: { fontWeight: 600, letterSpacing: '-0.02em', fontFamily: 'system-ui, sans-serif' },
  }
// Background scale in from center
  const bgScale = spring({ frame, fps, config: { stiffness: 120, damping: 18 } })

  // Parse numeric part from heroValue for count-up
  const numericMatch = heroValue.match(/([^0-9.]*)([0-9.]+)(.*)/)
  const prefix = numericMatch?.[1] ?? ''
  const numericPart = parseFloat(numericMatch?.[2] ?? '0')
  const suffix = numericMatch?.[3] ?? ''
  const isFloat = heroValue.includes('.')

  const numberSpring = spring({ frame: frame - 5, fps, config: { stiffness: 80, damping: 20 } })
  const animatedNumber = interpolate(numberSpring, [0, 1], [0, numericPart])
  const displayNumber = isFloat ? animatedNumber.toFixed(1) : Math.round(animatedNumber)

  // Label fade in
  const labelOpacity = spring({ frame: frame - 18, fps, config: { stiffness: 120, damping: 18 } })
  const labelY = interpolate(labelOpacity, [0, 1], [16, 0])

  // Parse stats
  const statItems = stats.split(',').map((s) => s.trim()).filter(Boolean).map((item) => {
    const parts = item.trim().split(' ')
    const label = parts[0]
    const value = parts.slice(1).join(' ')
    return { label, value }
  })

  return (
    <AbsoluteFill>
      {/* Full-bleed background — no expanding circle, just fade in */}
      <AbsoluteFill style={{
        backgroundColor: bgColor,
        opacity: interpolate(bgScale, [0, 1], [0, 1]),
      }} />

      {/* Giant number centered */}
      <AbsoluteFill style={{
        justifyContent: 'center',
        alignItems: 'center',
        paddingBottom: 120,
      }}>
        <div style={{
          fontSize: 200,
          fontWeight: 900,
          color: '#171717',
          fontFamily: s.fontFamily,
          letterSpacing: '-0.04em',
          lineHeight: 1,
        }}>
          {prefix}{displayNumber}{suffix}
        </div>

        {/* Label below */}
        <div style={{
          fontSize: 28,
          fontWeight: 500,
          color: '#171717',
          opacity: labelOpacity,
          transform: `translateY(${labelY}px)`,
          fontFamily: s.fontFamily,
          letterSpacing: s.letterSpacing,
          marginTop: 12,
        }}>
          {heroLabel}
        </div>
      </AbsoluteFill>

      {/* Supporting stats row at bottom */}
      <AbsoluteFill style={{
        justifyContent: 'flex-end',
        alignItems: 'center',
        paddingBottom: 80,
      }}>
        <div style={{
          display: 'flex',
          gap: 80,
        }}>
          {statItems.map((stat, i) => {
            const statSpring = spring({ frame: frame - 28 - i * 6, fps, config: { stiffness: 160, damping: 16 } })
            const statY = interpolate(statSpring, [0, 1], [40, 0])

            return (
              <div key={i} style={{
                textAlign: 'center',
                opacity: statSpring,
                transform: `translateY(${statY}px)`,
              }}>
                <div style={{
                  fontSize: 36,
                  fontWeight: 800,
                  color: '#171717',
                  fontFamily: s.fontFamily,
                  letterSpacing: '-0.02em',
                }}>
                  {stat.value}
                </div>
                <div style={{
                  fontSize: 14,
                  fontWeight: 500,
                  color: '#171717',
                  opacity: 0.6,
                  fontFamily: s.fontFamily,
                  marginTop: 4,
                  textTransform: 'uppercase',
                  letterSpacing: '0.08em',
                }}>
                  {stat.label}
                </div>
              </div>
            )
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  )
}

