    return result


def _scene(reader: PackReader, entry: dict[str, Any], curated: dict[str, Any]) -> dict[str, Any]:
    scene_id = str(entry.get("id", ""))
    component_path = _safe_relative(str(entry.get("file", f"{scene_id}/Composition.tsx")))
    metadata_path = f"{PurePosixPath(component_path).parent.as_posix()}/metadata.json"
    metadata = _json_object(reader.read_text(metadata_path), metadata_path)
    component_name = str(metadata.get("componentName", entry.get("componentName", "")))
    source = reader.read_text(component_path)
    static_parse = _static_parse(source, component_name)
    return {
        "id": scene_id,
        "name": str(metadata.get("name", scene_id)),
        "beat_type": str(curated["beat_type"]),
        "confidence": float(curated["confidence"]),
        "presentation": str(curated.get("presentation", "overlay")),
        "requires_numeric_claim": bool(curated.get("requires_numeric_claim", False)),
        "fixed_text_color": curated.get("fixed_text_color"),
        "engine": "remotion",
        "component_name": component_name,
        "component_path": component_path,
        "metadata_path": metadata_path,
        "duration_s": float(metadata["duration"]),
        "duration_in_frames": int(metadata["durationInFrames"]),
        "fps": int(metadata["fps"]),
        "width": int(metadata["width"]),
        "height": int(metadata["height"]),
        "slots": _slots(metadata, cast(dict[str, int], curated["max_chars"])),
        "status": static_parse["status"],
        "broken_reason": static_parse["reason"],
        "static_parse": static_parse,
    }


def build_scene_catalog(source: Path, output: Path) -> dict[str, Any]:
    """Scan the curated subset of an external pack and cache its catalog by source hash."""
    reader = PackReader.open(source)
    if output.exists():
        try:
            cached = _json_object(output.read_text(), str(output))
            cached_source = cached.get("source")
            if (
                cached.get("schema_version") == CATALOG_SCHEMA_VERSION
                and cached.get("curation_version") == CURATION_VERSION
                and isinstance(cached_source, dict)
                and cached_source.get("sha256") == reader.sha256
                and cached.get("source_sha256") == reader.sha256
            ):
                return cached
        except (OSError, TypeError, ValueError, json.JSONDecodeError):
            pass

    index = _json_array(reader.read_text("index.json"), "index.json")
    by_id = {str(item.get("id", "")): item for item in index}
    scenes: list[dict[str, Any]] = []
    for scene_id, curated in CURATED_SCENES.items():
        entry = by_id.get(scene_id)
        if entry is None:
            scenes.append(
                {
                    "id": scene_id,
                    "beat_type": curated["beat_type"],
                    "confidence": curated["confidence"],
                    "engine": "remotion",
                    "status": "broken",
                    "broken_reason": "curated scene is missing from index.json",
                    "static_parse": {
                        "status": "broken",
                        "parser": "palantum-static-v1",
                        "confidence": 1.0,
                        "reason": "curated scene is missing from index.json",
                    },
                }
            )
            continue
        try:
            scenes.append(_scene(reader, entry, curated))
        except (FileNotFoundError, KeyError, TypeError, ValueError, UnicodeDecodeError) as error:
            scenes.append(
                {
                    "id": scene_id,
                    "beat_type": curated["beat_type"],
                    "confidence": curated["confidence"],
                    "engine": "remotion",
                    "status": "broken",
                    "broken_reason": f"{type(error).__name__}: {error}",
                    "static_parse": {
                        "status": "broken",
                        "parser": "palantum-static-v1",
                        "confidence": 1.0,
                        "reason": f"{type(error).__name__}: {error}",
                    },
                }
            )
    catalog: dict[str, Any] = {
        "schema_version": CATALOG_SCHEMA_VERSION,
        "curation_version": CURATION_VERSION,
        "source_sha256": reader.sha256,
        "source": {
            "kind": reader.kind,
            "name": reader.source.name,
            "sha256": reader.sha256,
        },
        "scenes": scenes,
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    ]


_GENERIC_MOTION_SCENES = {
    "HOOK": ("brand-statement", "hero-stat-callout"),
    "PROBLEM": ("hero-stat-callout", "brand-statement"),
    "SOLUTION": ("step-explainer", "flowchart"),
    "DEMO": ("screen-showcase", "ui-walkthrough"),
    "TRACTION": ("saas-metrics-board", "bar-chart-reveal"),
    "TEAM": ("brand-statement", "hero-stat-callout"),
    "ASK": ("brand-statement", "hero-stat-callout"),
}


def _single_motion_scenes(catalog: dict[str, Any], beat: str) -> list[dict[str, Any]]:
    exact = [scene for scene in _selectable_scenes(catalog) if scene.get("type") == beat]
    if exact:
        return exact
    candidates = {
        str(scene.get("id")): scene
        for scene in catalog.get("scenes", [])
        if isinstance(scene, dict)
        and scene.get("status") == "ok"
        and scene.get("static_parse", {}).get("status") == "ok"
    }
    for scene_id in _GENERIC_MOTION_SCENES.get(beat, ()):
        if scene_id not in candidates:
            continue
        adapted = dict(candidates[scene_id])
        adapted["motion_variant_fallback"] = True
        adapted["adapted_from_type"] = adapted.get("type", "unclassified")
        adapted["type"] = beat
        adapted["confidence"] = max(0.7, float(adapted.get("confidence", 0)))
        return [adapted]
    return []


def _validate_overlay_plan(
    overlays: list[dict[str, Any]],
    scenes: list[dict[str, Any]],
    timeline: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    by_id = {str(scene["id"]): scene for scene in scenes}
    seen_slots: set[str] = set()
    validated: list[dict[str, Any]] = []
    for overlay in overlays:
        slot_id = str(overlay["slot_id"])
        if not re.fullmatch(r"[a-z0-9]+(?:[-_][a-z0-9]+)*", slot_id):
            raise ValueError(f"unsafe A6 slot_id: {slot_id}")
        if slot_id in seen_slots:
            raise ValueError(f"duplicate A6 slot_id: {slot_id}")
        seen_slots.add(slot_id)
        template_id = str(overlay["template_id"])
        if template_id not in by_id:
            raise ValueError(f"A6 selected unavailable template: {template_id}")
        scene = by_id[template_id]
        beat = str(overlay["beat"])
        if scene["type"] != beat:
            raise ValueError(f"A6 template {template_id} does not match beat {beat}")
        start = float(overlay["start_in_output"])
        duration = float(overlay["duration"])
        windows = [item for item in timeline if item["beat"] == beat]
        containing_windows = [
            item
            for item in windows
            if start >= float(item["start_in_output"]) - 1e-6
            and start < float(item["end_in_output"]) - 1e-6
        ]
        if not containing_windows and windows:
            window = min(
                windows,
                key=lambda item: abs(float(item["start_in_output"]) - start),
            )
            start = float(window["start_in_output"])
            containing_windows = [window]
        if containing_windows:
            available = max(float(item["end_in_output"]) - start for item in containing_windows)
            duration = min(duration, float(scene["duration_s"]), available)
        end = start + duration
        if duration <= 0:
            raise ValueError(f"A6 overlay {slot_id} has no usable duration")
        if not any(
            start >= float(item["start_in_output"]) - 1e-6
            and end <= float(item["end_in_output"]) + 1e-6
            for item in windows
        ):
            raise ValueError(f"A6 overlay {slot_id} falls outside its beat")
        slots = {
            str(item["key"]): int(item["max_chars"])
            for item in scene.get("slots", [])
            if isinstance(item, dict)
        }
        props = overlay["props"]
        unknown = sorted(set(props) - set(slots))
        if unknown:
            raise ValueError(f"A6 overlay {slot_id} has undeclared props: {', '.join(unknown)}")
        for key, value in props.items():
            if len(str(value)) > slots[key]:
                raise ValueError(f"A6 overlay {slot_id} prop {key} exceeds max_chars")
        enriched = dict(overlay)
        enriched["start_in_output"] = start
        enriched["duration"] = duration
        enriched["timeline_quote"] = " ".join(
            str(item.get("quote", "")) for item in containing_windows
        ).strip()
        enriched["scene"] = scene
        validated.append(enriched)
    ordered = sorted(validated, key=lambda item: float(item["start_in_output"]))
    for left, right in zip(ordered, ordered[1:], strict=False):
        if (
            float(left["start_in_output"]) + float(left["duration"])
            > float(right["start_in_output"]) + 1e-6
        ):
            raise ValueError("A6 overlays overlap")
    return validated


